233	func traceIDToJaegerProto(traceID pcommon.TraceID) model.TraceID {
234		traceIDHigh, traceIDLow := idutils.TraceIDToUInt64Pair(traceID)
235		return model.TraceID{
236			Low:  traceIDLow,
237			High: traceIDHigh,
238		}
239	}
