27	// FromDBModel converts multiple ES DB Spans to internal traces
28	func FromDBModel(spans []dbmodel.Span) (ptrace.Traces, error) {
29		traceData := ptrace.NewTraces()
30		if len(spans) == 0 {
31			return traceData, nil
32		}
33	
34		resourceSpans := traceData.ResourceSpans()
35		resourceSpans.EnsureCapacity(len(spans))
36		err := dbSpansToSpans(spans, resourceSpans)
37	
38		return traceData, err
39	}
