41	func dbProcessToResource(process dbmodel.Process, resource pcommon.Resource) {
42		serviceName := process.ServiceName
43		tags := process.Tags
44		if serviceName == "" && tags == nil {
45			return
46		}
47	
48		attrs := resource.Attributes()
49		if serviceName != "" && serviceName != noServiceName {
50			attrs.EnsureCapacity(len(tags) + 1)
51			attrs.PutStr(string(conventions.ServiceNameKey), serviceName)
52		} else {
53			attrs.EnsureCapacity(len(tags))
54		}
55		dbTagsToAttributes(tags, attrs)
56	}
