58	func dbSpansToSpans(dbSpans []dbmodel.Span, resourceSpans ptrace.ResourceSpansSlice) error {
59		for i := range dbSpans {
60			span := &dbSpans[i]
61			resourceSpan := resourceSpans.AppendEmpty()
62			dbProcessToResource(span.Process, resourceSpan.Resource())
63	
64			scopeSpans := resourceSpan.ScopeSpans()
65			scopeSpan := scopeSpans.AppendEmpty()
66			dbSpanToScope(span, scopeSpan)
67	
68			// TODO there should be no errors returned from translation from db model
69			err := dbSpanToSpan(span, scopeSpan.Spans().AppendEmpty())
70			if err != nil {
71				return err
72			}
73		}
74		return nil
75	}
