80			return err
81		}
82		spanId, err := fromDbSpanId(dbSpan.SpanID)
83		if err != nil {
84			return err
85		}
86		if dbSpan.ParentSpanID != "" {
87			parentSpanId, err := fromDbSpanId(dbSpan.ParentSpanID)
88			if err != nil {
89				return err
90			}
91			span.SetParentSpanID(parentSpanId)
92		}
93		span.SetTraceID(traceId)
94		span.SetSpanID(spanId)
95		span.SetName(dbSpan.OperationName)
96		span.SetFlags(dbSpan.Flags)
97	
98		startTime := model.EpochMicrosecondsAsTime(dbSpan.StartTime)
99		span.SetStartTimestamp(pcommon.NewTimestampFromTime(startTime))
100	
101		duration := model.MicrosecondsAsDuration(dbSpan.Duration)
102		endTime := startTime.Add(duration)
103		span.SetEndTimestamp(pcommon.NewTimestampFromTime(endTime))
104	
105		// TODO rewrite this to use a single loop over tags
106		// and map special tag names to OTEL Span fields
107		attrs := span.Attributes()
108		attrs.EnsureCapacity(len(dbSpan.Tags))
109		dbTagsToAttributes(dbSpan.Tags, attrs)
110		if spanKindAttr, ok := attrs.Get(model.SpanKindKey); ok {
111			span.SetKind(dbSpanKindToOTELSpanKind(spanKindAttr.Str()))
112			attrs.Remove(model.SpanKindKey)
113		}
114		setSpanStatus(attrs, span)
115	
116		span.TraceState().FromRaw(getTraceStateFromAttrs(attrs))
117	
118		// drop the attributes slice if all of them were replaced during translation
119		if attrs.Len() == 0 {
