191	func fromDBNumber(kv dbmodel.KeyValue, dest pcommon.Map) {
192		switch kv.Type {
193		case dbmodel.Int64Type:
194			switch v := kv.Value.(type) {
195			case int64:
196				dest.PutInt(kv.Key, v)
197			case float64:
198				// This case is possible as unmarshalling the JSON converts every int value to float64
199				dest.PutInt(kv.Key, int64(v))
200			case json.Number:
201				n, err := v.Int64()
