203					dest.PutInt(kv.Key, n)
204				}
205			default:
206				recordTagInvalidTypeError(kv, dest)
207			}
208		case dbmodel.Float64Type:
209			switch v := kv.Value.(type) {
210			case float64:
211				dest.PutDouble(kv.Key, v)
212			case json.Number:
213				n, err := v.Float64()
