	span.SetTraceID(pcommon.TraceID(dbSpan.TraceID))
	span.SetSpanID(dbSpanIDToOTEL(dbSpan.SpanID))
	span.SetName(dbSpan.OperationName)
	span.SetFlags(uint32(dbSpan.Flags))

	startTime := model.EpochMicrosecondsAsTime(uint64(dbSpan.StartTime))
	span.SetStartTimestamp(pcommon.NewTimestampFromTime(startTime))
	endTime := startTime.Add(model.MicrosecondsAsDuration(uint64(dbSpan.Duration)))
	span.SetEndTimestamp(pcommon.NewTimestampFromTime(endTime))

	parentSpanID := dbParentSpanID(dbSpan)
	if parentSpanID != 0 {
		span.SetParentSpanID(dbSpanIDToOTEL(parentSpanID))
	}

	attrs := span.Attributes()
	attrs.EnsureCapacity(len(dbSpan.Tags))
	dbTagsToAttributes(dbSpan.Tags, attrs)
	if spanKindAttr, ok := attrs.Get(model.SpanKindKey); ok {
		span.SetKind(dbSpanKindToOTELSpanKind(spanKindAttr.Str()))
		attrs.Remove(model.SpanKindKey)
	}
	setSpanStatus(attrs, span)

	span.TraceState().FromRaw(getTraceStateFromAttrs(attrs))

	// drop the attributes slice if all of them were replaced during translation
	if attrs.Len() == 0 {
		attrs.Clear()
	}

	dbLogsToSpanEvents(dbSpan.Logs, span.Events())
	dbRefsToSpanLinks(dbSpan.Refs, parentSpanID, span.Links())
