// dbParentSpanID returns the span ID of the first CHILD_OF reference that
// belongs to the same trace as the span, i.e. its parent. Returns 0 when the
// span has no parent.
func dbParentSpanID(span *dbmodel.Span) int64 {
	for i := range span.Refs {
		ref := &span.Refs[i]
		if ref.RefType == dbmodel.ChildOf && ref.TraceID == span.TraceID {
			return ref.SpanID
		}
	}
	return 0
}

